// Actual built pages and owned production handlers; provider objects are signed
// fixtures from private-state-server, never hosted Stripe acceptance.
import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import {careToken} from '../../server/lib/care-contract.js';
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {createRequire} from 'node:module';
const require=createRequire(process.cwd()+'/package.json'),{Pool}=require('pg');
const br=createRequire(process.env.SDS_BROWSER_MODULES+'/package.json'),puppeteer=br('puppeteer-core');
const origin=process.env.SDS_PREVIEW_ORIGIN||'http://127.0.0.1:31861',out=process.env.SDS_STATE_OUT,links=JSON.parse(await readFile(process.env.SDS_STATE_LINKS));
assert.ok(out&&new URL(process.env.SDS_LOCAL_DATABASE_URL).hostname==='127.0.0.1');await mkdir(out,{recursive:true});
const pool=new Pool({connectionString:process.env.SDS_LOCAL_DATABASE_URL});const axe=await readFile(br.resolve('axe-core/axe.min.js'),'utf8');
const browser=await puppeteer.launch({executablePath:'/usr/local/bin/google-chrome',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});
const report={source:process.env.SDS_SOURCE,provider:'signed local fixtures; no hosted Stripe acceptance',views:[],actions:[]};
// Keep the real request pending until the loading assertion and screenshot finish.
// CPU-dependent delays can expire while axe or a full-page capture is still running.
async function holdPost(page,pathname){
 await page.setRequestInterception(true);let held,resolve;const started=new Promise(r=>{resolve=r});
 const intercept=request=>{if(!held&&request.method()==='POST'&&new URL(request.url()).pathname===pathname){held=request;resolve()}else void request.continue()};page.on('request',intercept);
 return {started,async release(){page.off('request',intercept);if(held){await held.continue();held=null}await page.setRequestInterception(false)}};
}
async function shot(page,name,width,theme){await page.addScriptTag({content:axe});const r=await page.evaluate(async()=>{const a=await axe.run(document,{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21a','wcag21aa']}});return {axe:a.violations.map(v=>({id:v.id,nodes:v.nodes.map(n=>({target:n.target,summary:n.failureSummary}))})),width:innerWidth,scrollWidth:document.documentElement.scrollWidth,text:document.querySelector('main')?.innerText};});const screenshot=name+'-'+width+'-'+theme+'.jpg';await page.screenshot({path:out+'/'+screenshot,fullPage:true,type:'jpeg',quality:72});report.views.push({name,width,theme,screenshot,...r,trace:page.__auditTrace.splice(0),expectedStatusCodes:name==='receipt-invalid-link'?[403,404]:name==='checkout-expired-refusal'?[409]:name==='task-recoverable-error'?[503]:[]});await writeFile(out+'/report.json',JSON.stringify(report,null,2));}
try{for(const width of [390,768,1440])for(const theme of ['drafting','dark']){
 const context=await browser.createBrowserContext(),page=await context.newPage();
 page.__auditTrace=[];
 const safePath=url=>{try{return new URL(url).pathname.replace(/[0-9a-f]{8}-[0-9a-f-]{27,}/ig,':id')}catch{return '[invalid URL]'}};
 page.on('console',m=>{if(m.type()==='error')page.__auditTrace.push({type:'console_error',text:m.text().replace(/https?:\/\/[^\s)]+/g,safePath).slice(0,400)})});
 page.on('pageerror',e=>page.__auditTrace.push({type:'page_error',text:e.message.replace(/https?:\/\/[^\s)]+/g,safePath).slice(0,400)}));
 page.on('response',r=>{if(r.status()>=400)page.__auditTrace.push({type:'http_error',path:safePath(r.url()),status:r.status()})});
 page.on('requestfailed',r=>{const boundary=['checkout.stripe.com','billing.stripe.com'].includes(new URL(r.url()).hostname);page.__auditTrace.push({type:boundary?'intentional_fixture_handoff_boundary':'request_failed',path:safePath(r.url()),error:r.failure()?.errorText})});
 await page.setViewport({width,height:900});await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);await page.evaluateOnNewDocument(t=>{if(location.protocol==='http:'||location.protocol==='https:')localStorage.setItem('sdd-theme',t)},theme);
 for(const link of links.filter(x=>!x.name.startsWith('action-'))){await page.goto("about:blank");await page.goto(origin+link.path,{waitUntil:'networkidle0'});if(link.name!=='manage-renewal')await page.waitForFunction(()=>!document.body.innerText.includes('Opening your receipt'));assert.equal(new URL(page.url()).hash,'','receipt capability removed from address');await shot(page,'receipt-'+link.name,width,theme);
 if(link.name==='manage-renewal'){
  await page.setRequestInterception(true);let portalHost;const portalBoundary=r=>{if(r.isNavigationRequest()&&new URL(r.url()).hostname==='billing.stripe.com'){portalHost='billing.stripe.com';void r.abort('aborted')}else void r.continue()};page.on('request',portalBoundary);
  await page.locator('button').click();for(let n=0;n<100&&!portalHost;n++)await new Promise(r=>setTimeout(r,50));assert.equal(portalHost,'billing.stripe.com');await shot(page,'subscription-portal-handoff',width,theme);report.actions.push({name:'real-subscription-handler-to-fixture-portal',width,theme,passed:true,hostedAcceptance:false});page.off('request',portalBoundary);await page.setRequestInterception(false);
 }
 }
 await page.goto('about:blank');await page.goto(origin+'/care/intake#order=00000000-0000-4000-8000-000000000001&key=invalid',{waitUntil:'networkidle0'});await page.waitForSelector('[role=alert]');await shot(page,'receipt-invalid-link',width,theme);
 const orderId=randomUUID();const started=await fetch(origin+'/api/care/checkout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({offer:'agent_front_door',order:orderId})});assert.equal(started.status,200);
 const stored=(await pool.query('select session_id from public.care_orders where id=$1',[orderId])).rows[0];const object={id:stored.session_id,livemode:false,mode:'payment',client_reference_id:orderId,currency:'usd',amount_total:24900,metadata:{sds_care_order:orderId},status:'complete',payment_status:'paid',payment_intent:'pi_'+orderId.replaceAll('-',''),customer:'cus_fixture',customer_details:{email:'buyer@example.test'}};
 const action={path:'/care/intake#'+new URLSearchParams({order:orderId,key:careToken('isolated care access secret sufficient length',orderId,'intake')})};
 const loading=await holdPost(page,'/api/care/receipt');try{await page.goto('about:blank');await page.goto(origin+action.path,{waitUntil:'domcontentloaded'});await loading.started;await page.waitForFunction(()=>document.body.innerText.includes('Opening your receipt'));await shot(page,'receipt-request-loading',width,theme);assert.ok(await page.evaluate(()=>document.body.innerText.includes('Opening your receipt')));}finally{await loading.release()}await page.waitForFunction(()=>document.body.innerText.includes('Waiting for payment confirmation.'));await shot(page,'receipt-payment-waiting',width,theme);
 const pendingRead=page.waitForResponse(r=>new URL(r.url()).pathname==='/api/care/receipt');await page.locator('button').click();assert.equal((await pendingRead).status(),200);assert.ok(await page.$('button'));
 const Stripe=require('stripe'),signer=new Stripe('sk_test_private_fixture'),payload=JSON.stringify({type:'checkout.session.completed',livemode:false,created:Math.floor(Date.now()/1000),data:{object}}),signature=signer.webhooks.generateTestHeaderString({payload,secret:'whsec_private_fixture'});const received=await fetch(origin+'/api/stripe/webhook',{method:'POST',headers:{'Content-Type':'application/json','Stripe-Signature':signature},body:payload});assert.equal(received.status,200);
 const paidRead=page.waitForResponse(r=>new URL(r.url()).pathname==='/api/care/receipt');await page.locator('button').click();assert.equal((await paidRead).status(),200);await page.waitForSelector('form input[name=surface]');await shot(page,'receipt-payment-refreshed',width,theme);report.actions.push({name:'pending-refresh-after-signed-handler-commit',width,theme,passed:true,providerReceipt:false});await page.locator('form button[type=submit]').click();assert.equal(await page.$eval('input[name=surface]',e=>e.validity.valueMissing),true);await shot(page,'intake-validation',width,theme);
 await page.type('input[name=surface]','The example booking workflow');await page.type('textarea[name=outcome]','An assistant can book the requested appointment.');await page.locator('form button[type=submit]').click();await page.waitForSelector('[role=status]');await shot(page,'intake-received',width,theme);await page.reload({waitUntil:'networkidle0'});await page.waitForFunction(()=>document.body.innerText.includes('We received your workflow.'));assert.equal(await page.$('form'),null);report.actions.push({name:'paid-intake-durable-after-reload',width,theme,passed:true});
 const expired=links.find(x=>x.name==='expired');const order=new URLSearchParams(expired.path.split('#')[1]).get('order');await page.goto(origin+'/care/buy?offer=agent_front_door&left=1',{waitUntil:'networkidle0'});await page.evaluate(id=>sessionStorage.setItem('sds-care-order:agent_front_door',id),order);await page.locator('button').click();await page.waitForSelector('[role=alert]');await shot(page,'checkout-expired-refusal',width,theme);assert.equal(await page.evaluate(()=>sessionStorage.getItem('sds-care-order:agent_front_door')),null);
 await page.setRequestInterception(true);let handoff;const intercept=r=>{if(r.isNavigationRequest()&&new URL(r.url()).origin!==origin){handoff=new URL(r.url()).origin;void r.abort();}else void r.continue();};page.on('request',intercept);await page.locator('button').click();await new Promise(r=>setTimeout(r,1000));assert.equal(handoff,'https://checkout.stripe.com');report.actions.push({name:'owned-checkout-handler-to-fixture-hosted-handoff',width,theme,passed:true,hostedAcceptance:false});page.off('request',intercept);await page.setRequestInterception(false);
 await page.goto(origin+'/#task',{waitUntil:'networkidle0'});await page.waitForSelector('textarea[name=task]');await page.evaluate(async()=>{for(let y=0;y<document.body.scrollHeight;y+=700){window.scrollTo(0,y);await new Promise(r=>requestAnimationFrame(r));}});await page.locator('textarea[name=task]').fill('Review this synthetic booking workflow and return a fixed scope.');await page.locator('input[name=email]').fill('buyer@example.test');
 await pool.query("create or replace function public.sds_acceptance_refuse() returns trigger language plpgsql as $$ begin raise exception 'isolated acceptance refusal'; end $$");await pool.query('create trigger sds_acceptance_refuse before insert on public.task_requests for each row execute function public.sds_acceptance_refuse()');
 try{await page.locator('form:has(textarea[name=task]) button[type=submit]').click();await page.waitForSelector('[role=alert]');await shot(page,'task-recoverable-error',width,theme);}finally{await pool.query('drop trigger if exists sds_acceptance_refuse on public.task_requests');}
 await pool.query("create or replace function public.sds_acceptance_delay() returns trigger language plpgsql as $$ begin perform pg_sleep(1); return new; end $$");await pool.query('create trigger sds_acceptance_delay before insert on public.task_requests for each row execute function public.sds_acceptance_delay()');
 const transport=await holdPost(page,'/api/requests');
 try{await page.locator('form:has(textarea[name=task]) button[type=submit]').click();await transport.started;await page.waitForSelector('form:has(textarea[name=task]) button[disabled]');await shot(page,'task-sending',width,theme);assert.equal(await page.$eval('form:has(textarea[name=task]) button[type=submit]',e=>e.disabled),true);await transport.release();await page.waitForFunction(()=>document.body.innerText.includes('We have your task.'));await shot(page,'task-received',width,theme);}finally{await transport.release();await pool.query('drop trigger if exists sds_acceptance_delay on public.task_requests');}
 await context.close();console.log('STATES',width,theme,'passed');
}}finally{await pool.query('drop trigger if exists sds_acceptance_refuse on public.task_requests');await pool.query('drop trigger if exists sds_acceptance_delay on public.task_requests');await pool.end();await browser.close();await writeFile(out+'/report.json',JSON.stringify(report,null,2));}
